function expandSearchTokens(rawQuery) {
  const words = rawQuery.toLowerCase().split(/\s+/).filter(Boolean);
  return words.map(word => {
    const expanded = new Set([word]);
    for (const group of SEARCH_SYNONYM_GROUPS) {
      if (group.some(term => term.includes(word) || word.includes(term))) {
        for (const term of group) expanded.add(term);
      }
    }
    return Array.from(expanded);
  });
}

function matchesItemWithAliases(item, catName, rawQuery) {
  if (!rawQuery) return true;
  const hay = [
    item.name,
    item.composition || "",
    catName || "",
    ...(item.aliases || [])
  ].join(" ").toLowerCase();

  const tokenGroups = expandSearchTokens(rawQuery);
  // Every word typed by user must match either directly or via one of its synonyms/aliases
  return tokenGroups.every(group => group.some(variant => hay.includes(variant)));
}


function escapeHtml(str) {
  if (!str) return "";
  return String(str)
    .replace(/&/g, "&amp;")
    .replace(/</g, "&lt;")
    .replace(/>/g, "&gt;")
    .replace(/"/g, "&quot;");
}

function renderCategories() {
  const rail = document.getElementById("categoryRail");
  if (!rail) return;
  let html = `<button class="cat-pill ${activeCategoryId === 'all' ? 'is-active' : ''}" onclick="selectCategory('all')">Усе</button>`;
  for (const cat of MENU_DATA.categories) {
    const active = activeCategoryId === cat.id ? "is-active" : "";
    html += `<button class="cat-pill ${active}" onclick="selectCategory('${cat.id}')">${escapeHtml(cat.name)}</button>`;
  }
  rail.innerHTML = html;
}

function selectCategory(catId) {
  activeCategoryId = catId;
  renderCategories();
  renderCatalog();
  if (catId !== "all") {
    const sec = document.getElementById("sec-" + catId);
    if (sec) sec.scrollIntoView({ behavior: "smooth", block: "start" });
  }
}

function handleSearch(val) {
  searchQuery = (val || "").trim().toLowerCase();
  renderCatalog();
}

function renderCard(item) {
  const imgSrc = item.photo?.local_url || item.photo?.thumb_url || "";
  const desc = item.composition ? escapeHtml(item.composition) : "";
  const weight = (item.weight && item.weight !== "—") ? escapeHtml(item.weight) : "";

  if (CARD_VARIANT === "nordqr") {
    return `
      <article class="dish-item" onclick="openDish('${item.id}')">
        <div class="dish-item__info">
          <div class="dish-item__header">
            <h3 class="dish-item__title">${escapeHtml(item.name)}</h3>
            ${weight ? `<span class="dish-item__weight">${weight}</span>` : ""}
          </div>
          ${desc ? `<p class="dish-item__desc">${desc}</p>` : ""}
          <div class="dish-item__price">${escapeHtml(item.price)}</div>
        </div>
        <div class="dish-item__photo">
          <img src="${escapeHtml(imgSrc)}" alt="${escapeHtml(item.name)}" loading="lazy" />
        </div>
      </article>
    `;
  }

  if (CARD_VARIANT === "grid") {
    return `
      <article class="dish-item" onclick="openDish('${item.id}')">
        <div class="dish-item__photo">
          <img src="${escapeHtml(imgSrc)}" alt="${escapeHtml(item.name)}" loading="lazy" />
          ${weight ? `<span class="dish-item__weight-badge">${weight}</span>` : ""}
        </div>
        <div class="dish-item__info">
          <h3 class="dish-item__title">${escapeHtml(item.name)}</h3>
          ${desc ? `<p class="dish-item__desc">${desc}</p>` : ""}
          <div class="dish-item__footer">
            <span class="dish-item__price">${escapeHtml(item.price)}</span>
          </div>
        </div>
      </article>
    `;
  }

  return `
    <article class="dish-item" onclick="openDish('${item.id}')">
      <div class="dish-item__photo">
        <img src="${escapeHtml(imgSrc)}" alt="${escapeHtml(item.name)}" loading="lazy" />
      </div>
      <div class="dish-item__info">
        <h3 class="dish-item__title">${escapeHtml(item.name)}</h3>
        ${desc ? `<p class="dish-item__desc">${desc}</p>` : ""}
        <div class="dish-item__meta">
          <span class="dish-item__price">${escapeHtml(item.price)}</span>
          ${weight ? `<span class="dish-item__weight">${weight}</span>` : ""}
        </div>
      </div>
    </article>
  `;
}

function renderCatalog() {
  const container = document.getElementById("catalogContainer");
  if (!container) return;
  let html = "";

  for (const cat of MENU_DATA.categories) {
    if (activeCategoryId !== "all" && activeCategoryId !== cat.id) continue;

    const items = cat.items.filter(it => matchesItemWithAliases(it, cat.name, searchQuery));

    if (!items.length) continue;

    html += `
      <section class="menu-section" id="sec-${cat.id}">
        <div class="menu-section__head">
          <h2 class="menu-section__title">${escapeHtml(cat.name)}</h2>
          <span class="menu-section__count">${items.length}</span>
        </div>
        <div class="menu-section__list">
          ${items.map(it => renderCard(it)).join("")}
        </div>
      </section>
    `;
  }

  if (!html) {
    html = `<div class="empty-state">За вашим запитом страв не знайдено.</div>`;
  }

  container.innerHTML = html;
}

function openDish(dishId) {
  let found = null;
  let foundCat = null;
  for (const cat of MENU_DATA.categories) {
    for (const it of cat.items) {
      if (it.id === dishId) {
        found = it;
        foundCat = cat;
        break;
      }
    }
  }
  if (!found) return;

  const modalImg = document.getElementById("modalImg");
  modalImg.src = found.photo?.local_url || found.photo?.thumb_url || "";
  modalImg.alt = found.name;

  document.getElementById("modalCategory").textContent = foundCat.name;
  document.getElementById("modalTitle").textContent = found.name;
  document.getElementById("modalPrice").textContent = found.price;

  const weightEl = document.getElementById("modalWeight");
  if (found.weight && found.weight !== "—") {
    weightEl.textContent = found.weight;
    weightEl.style.display = "inline-block";
  } else {
    weightEl.style.display = "none";
  }

  const compWrap = document.getElementById("modalCompWrap");
  const compText = document.getElementById("modalComp");
  if (found.composition) {
    compText.textContent = found.composition;
    compWrap.style.display = "block";
  } else {
    compWrap.style.display = "none";
  }

  document.getElementById("dishModal").classList.add("is-open");
}

function closeDish(e) {
  if (e && e.target !== document.getElementById("dishModal")) return;
  document.getElementById("dishModal").classList.remove("is-open");
}

document.addEventListener("DOMContentLoaded", () => {
  renderCategories();
  renderCatalog();
});
